item.command:
/usr/bin/bash -lc "python3 - <<'PY'
import random
random.seed(103)
pieces={}
for x in range(8):
 for y,c in [(0,'W'),(1,'W'),(6,'B'),(7,'B')]: pieces[(x,y)]=c
for x in [1,6]:
 pieces[(x,0)]='w';pieces[(x,7)]='b'
seen={}
moves=[]
for i in range(50):
 side='w' if i%2==0 else 'b'
 candidates=[]
 for (x,y),p in pieces.items():
  if p"'!=side: continue
  for dx,dy in [(1,2),(-1,2),(1,-2),(-1,-2),(2,1),(-2,1),(2,-1),(-2,-1)]:
   t=(x+dx,y+dy)
   if 0<=t[0]<8 and 0<=t[1]<8 and t not in pieces:
    cp=pieces.copy();cp[t]=cp.pop((x,y))
    state=(i%2,tuple(sorted(cp.items())))
    if seen.get(state,0)<2: candidates.append(((x,y),t,cp,state))
 if not candidates: break
 source,dest,pieces,state=random.choice(candidates)
 seen[state]=seen.get(state,0)+1
 def fmt(v):return chr(65+v[0])+str(v[1]+1)
 moves.append((fmt(source),fmt(dest)))
print(len(moves))
for i in range(0,len(moves),2):print('"'    ('+ ', '.join(f'({a}, {b})' for a,b in moves[i:i+2])+'),')
PY"

